-- Módulo 34 OrdenesProduccion: órdenes para fabricar un producto con su lista de materiales y su ruta activas.
-- Spec: docs/specs/modulo34-ordenes-produccion-backend.md (§4).

CREATE TABLE "OrdenesProduccion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "ProductoId" integer NOT NULL,
    "ListaMaterialesId" integer NOT NULL,
    "RutaProduccionId" integer NOT NULL,
    "CantidadPlanificada" integer NOT NULL,
    "CantidadProducida" integer,
    "FechaInicioPlanificada" date NOT NULL,
    "FechaFinPlanificada" date NOT NULL,
    "FechaInicioReal" timestamp with time zone,
    "FechaFinReal" timestamp with time zone,
    "Estado" character varying(12) NOT NULL,
    "MotivoCancelacion" character varying(250),
    CONSTRAINT "PK_OrdenesProduccion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrdenesProduccion_Productos_ProductoId"
        FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_OrdenesProduccion_ListasMateriales_ListaMaterialesId"
        FOREIGN KEY ("ListaMaterialesId") REFERENCES "ListasMateriales" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_OrdenesProduccion_RutasProduccion_RutaProduccionId"
        FOREIGN KEY ("RutaProduccionId") REFERENCES "RutasProduccion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_OrdenesProduccion_CantidadPlanificada" CHECK ("CantidadPlanificada" > 0),
    CONSTRAINT "CK_OrdenesProduccion_CantidadProducida" CHECK ("CantidadProducida" IS NULL OR "CantidadProducida" >= 0),
    CONSTRAINT "CK_OrdenesProduccion_FechasPlanificadas" CHECK ("FechaFinPlanificada" >= "FechaInicioPlanificada"),
    CONSTRAINT "CK_OrdenesProduccion_Estado"
        CHECK ("Estado" IN ('Planificada', 'Liberada', 'EnProceso', 'Terminada', 'Cancelada'))
);

CREATE UNIQUE INDEX "IX_OrdenesProduccion_Numero" ON "OrdenesProduccion" ("Numero");
CREATE INDEX "IX_OrdenesProduccion_ProductoId" ON "OrdenesProduccion" ("ProductoId");
CREATE INDEX "IX_OrdenesProduccion_ListaMaterialesId" ON "OrdenesProduccion" ("ListaMaterialesId");
CREATE INDEX "IX_OrdenesProduccion_RutaProduccionId" ON "OrdenesProduccion" ("RutaProduccionId");
CREATE INDEX "IX_OrdenesProduccion_Estado" ON "OrdenesProduccion" ("Estado");
